"""Tests for observation_validator.py."""

import copy

import pytest

from observation_validator import (
    UCUM_SYSTEM,
    validate,
)


# ---------------------------------------------------------------------------
# Fixtures / helpers
# ---------------------------------------------------------------------------

def make_resource(**overrides):
    """A fully valid Observation fixture, overridden per-test."""
    resource = {
        "resourceType": "Observation",
        "status": "final",
        "code": {"text": "Hemoglobin"},
        "subject": {"reference": "Patient/123"},
        "valueQuantity": {
            "value": 13.5,
            "unit": "g/dL",
            "system": UCUM_SYSTEM,
        },
        "referenceRange": {
            "low": {"value": 12.0, "unit": "g/dL", "system": UCUM_SYSTEM},
            "high": {"value": 16.0, "unit": "g/dL", "system": UCUM_SYSTEM},
        },
    }
    resource.update(overrides)
    return resource


VALID_FIXTURES = [
    {
        "name": "final with quantity and range",
        "resource": make_resource(),
    },
    {
        "name": "registered without value/range",
        "resource": {
            "resourceType": "Observation",
            "status": "registered",
            "code": {"text": "Blood culture"},
            "subject": {"reference": "Patient/abc-9"},
        },
    },
]

STATUSES = ["registered", "preliminary", "final", "amended"]


def error_paths(result):
    return {e["path"] for e in result["errors"]}


# ---------------------------------------------------------------------------
# Fully valid fixtures
# ---------------------------------------------------------------------------

@pytest.mark.parametrize("fixture", VALID_FIXTURES, ids=lambda f: f["name"])
def test_valid_fixtures(fixture):
    result = validate(fixture["resource"])
    assert result["errors"] == []
    assert result["valid"] is True
    assert result["interpretation"] == "N"  # 13.5 within [12.0, 16.0]


# ---------------------------------------------------------------------------
# Cross-field matrix: 4 statuses x value present/absent
# ---------------------------------------------------------------------------

@pytest.mark.parametrize("status", STATUSES)
@pytest.mark.parametrize("with_value", [True, False])
def test_status_value_matrix(status, with_value):
    resource = make_resource(status=status)
    if not with_value:
        del resource["valueQuantity"]
        del resource["referenceRange"]

    result = validate(resource)

    if status == "final" and not with_value:
        assert not result["valid"]
        assert "/valueQuantity" in error_paths(result)
    else:
        assert result["valid"], result["errors"]

    # interpretation needs both sides; absent for value-less resources
    if not with_value:
        assert result["interpretation"] is None


# ---------------------------------------------------------------------------
# referenceRange violations
# ---------------------------------------------------------------------------

def test_range_low_not_less_than_high():
    resource = make_resource()
    resource["referenceRange"] = {
        "low": {"value": 16.0, "unit": "g/dL", "system": UCUM_SYSTEM},
        "high": {"value": 16.0, "unit": "g/dL", "system": UCUM_SYSTEM},
    }
    result = validate(resource)
    assert not result["valid"]
    assert "/referenceRange/high/value" in error_paths(result)


def test_range_low_greater_than_high():
    resource = make_resource()
    resource["referenceRange"] = {
        "low": {"value": 20.0, "unit": "g/dL", "system": UCUM_SYSTEM},
        "high": {"value": 10.0, "unit": "g/dL", "system": UCUM_SYSTEM},
    }
    result = validate(resource)
    assert not result["valid"]
    assert "/referenceRange/high/value" in error_paths(result)


@pytest.mark.parametrize("side", ["low", "high"])
def test_range_unit_mismatch(side):
    resource = make_resource()
    resource["referenceRange"][side]["unit"] = "mg/L"
    result = validate(resource)
    assert not result["valid"]
    assert f"/referenceRange/{side}/unit" in error_paths(result)


# ---------------------------------------------------------------------------
# Interpretation on all three sides, boundary equality counts as "N"
# ---------------------------------------------------------------------------

@pytest.mark.parametrize("value,expected", [
    (5.0, "L"),     # below low
    (12.0, "N"),    # boundary equality with low counts as N
    (14.0, "N"),    # inside range
    (16.0, "N"),    # boundary equality with high counts as N
    (25.0, "H"),    # above high
])
def test_interpretation_sides_and_boundaries(value, expected):
    result = validate(make_resource(valueQuantity={
        "value": value, "unit": "g/dL", "system": UCUM_SYSTEM}))
    assert result["valid"]
    assert result["interpretation"] == expected


# ---------------------------------------------------------------------------
# Field-level schema violations (spot checks with pointer assertions)
# ---------------------------------------------------------------------------

def test_wrong_resource_type():
    result = validate(make_resource(resourceType="DiagnosticReport"))
    assert "/resourceType" in error_paths(result)


@pytest.mark.parametrize("bad_status", ["cancelled", "", None])
def test_bad_status(bad_status):
    resource = make_resource(status=bad_status)
    result = validate(resource)
    assert "/status" in error_paths(result)


@pytest.mark.parametrize("text", ["", "   ", None, 42])
def test_bad_code_text(text):
    resource = make_resource(code={"text": text})
    result = validate(resource)
    assert "/code/text" in error_paths(result)


@pytest.mark.parametrize("ref", ["Patient/", "Observation/1",
                                 "Patient/a b", None, 7])
def test_bad_subject_reference(ref):
    resource = make_resource(subject={"reference": ref})
    result = validate(resource)
    assert "/subject/reference" in error_paths(result)


@pytest.mark.parametrize("bad_vq", [
    {"value": "13.5", "unit": "g/dL", "system": UCUM_SYSTEM},   # non-number
    {"value": 13.5, "system": UCUM_SYSTEM},                     # unit missing
    {"value": 13.5, "unit": "g/dL",
     "system": "http://wrong.example"},                         # wrong system
    {"value": True, "unit": "g/dL", "system": UCUM_SYSTEM},     # bool != number
])
def test_bad_value_quantity(bad_vq):
    result = validate(make_resource(valueQuantity=bad_vq))
    assert not result["valid"]
    assert any(p.startswith("/valueQuantity/") for p in error_paths(result))


def test_non_object_resource():
    result = validate([1, 2, 3])
    assert not result["valid"]
    assert result["interpretation"] is None


def test_errors_are_structured():
    result = validate(make_resource(status="nope", code={"text": ""}))
    for err in result["errors"]:
        assert set(err.keys()) == {"path", "message"}
        assert isinstance(err["path"], str)
        assert isinstance(err["message"], str)

